KPhysicalMask.both_tests_full_masked_kernel_net.{u_1, u_2} (K : Type u_1) [Field K] [NumberField K]
  [MeasurableSpace (MasulloGRH.HeckeAdeles K)] [MeasurableMul₂ (MasulloGRH.HeckeIdeleClasses K)]
  [MeasurableInv (MasulloGRH.HeckeIdeleClasses K)] (addHaar : Measure (MasulloGRH.HeckeAdeles K))
  (mu : Measure (MasulloGRH.HeckeIdeleClasses K)) [mu.IsMulLeftInvariant] [SigmaFinite mu] [IsLocallyFiniteMeasure mu]
  [mu.IsInvInvariant] {ι : Type u_2} (f : Filter ι) [f.IsCountablyGenerated] (a l r s : ℝ) (hlr : l ≤ r) (hs : 0 ≤ s)
  (phi : MasulloGRH.HeckeIdeleClasses K → ℂ) (hh : Continuous phi) (hc : HasCompactSupport phi)
  (hphi : ∀ (x : MasulloGRH.HeckeIdeleClasses K), Masullo.IdeleClassGeometry.classLog K x = 0 → phi x = 0) (q : Fin 2)
  (Lambda epsilon : ι → ℝ) (hLambda : Tendsto Lambda f atTop)
  (hprod : Tendsto (fun i => epsilon i * Lambda i) f (nhds 0)) (rho : ι → MasulloGRH.HeckeIdeleClasses K → ℝ)
  (hm : ∀ (i : ι), Measurable (rho i)) (hb : ∀ (i : ι) (x : MasulloGRH.HeckeIdeleClasses K), 0 ≤ rho i x ∧ rho i x ≤ 1)
  (hp :
    ∀ᶠ (i : ι) in f,
      ∀ (x : MasulloGRH.HeckeIdeleClasses K),
        (Lambda i)⁻¹ + epsilon i ≤ Real.exp (Masullo.IdeleClassGeometry.classLog K x) →
          Real.exp (Masullo.IdeleClassGeometry.classLog K x) ≤ Lambda i - epsilon i → rho i x = 1)
  (F : ↥(Lp ℂ 2 mu)) :
  have ht := ⋯;
  have A := PIntervalConvolution.intervalConvolutionCLM K mu l r s hlr hs (LIntegrated.requiredTest K phi q) ⋯ ⋯;
  let E :=
    DSourceKernel.sourceSpan mu 0 0 (OAllCharacterClosure.fullSourceMap K addHaar mu (a + (l + r) / 2) ((r - l) / 2) s);
  have S := (JThetaAttachment.fullThetaClosure K addHaar mu (a + (l + r) / 2) ((r - l) / 2) s).starProjection;
  have PA := (1 - S).comp A;
  have b := fun x => PIntervalConvolution.intervalHalfWeight l r s (Masullo.IdeleClassGeometry.classLog K x);
  have k := fun T => DSourceKernel.residualKernel mu b (E T) A fun x y => LIntegrated.requiredTest K phi q (x * y⁻¹);
  have M := fun i => KPhysicalMask.realMaskCLM mu (rho i) ⋯ ⋯;
  have kF := fun z x =>
    ↑(rho z.1 x) * (↑(b x) * ∫ (y : MasulloGRH.HeckeIdeleClasses K), k z.2 x y * (↑↑F y / ↑(b y)) ∂mu);
  (∀ (z : ι × Finset ↥(Lp ℂ 2 mu)), (fun x => ↑↑((M z.1) (A F - (E z.2).starProjection (A F))) x) =ᶠ[ae mu] kF z) ∧
    ∃ (hi : ∀ (z : ι × Finset ↥(Lp ℂ 2 mu)), MemLp (kF z) 2 mu),
      (∀ (z : ι × Finset ↥(Lp ℂ 2 mu)), MemLp.toLp (kF z) ⋯ = (M z.1) (A F - (E z.2).starProjection (A F))) ∧
        Tendsto (fun z => MemLp.toLp (kF z) ⋯) (f ×ˢ atTop) (nhds (PA F))
